<div class="form-group"><label for="category">Kategori</label><select id="category" name="category" required><option value="">Pilih Kategori</option><?php foreach(['Food', 'Drink', 'Stationery', 'Uniform'] as $option):?><option value="<?=e($option)?>" <?=(($data['category'] ?? '')===$option)?'selected':''?>><?=e($option)?></option><?php endforeach?></select><?php if(isset($errors['category'])):?><p class="error-text"><?=e($errors['category'])?></p><?php endif?></div>
<div class="form-group"><label>Satuan</label><div class="choice-group"><?php foreach(['Pcs', 'Pack', 'Bottle'] as $option):?><label><input type="radio" name="unit" value="<?=e($option)?>" <?=(($data['unit'] ?? '')===$option)?'checked':''?> required> <?=e($option==='M'?'Laki-laki':($option==='F'?'Perempuan':$option))?></label><?php endforeach?></div><?php if(isset($errors['unit'])):?><p class="error-text"><?=e($errors['unit'])?></p><?php endif?></div>
<div class="form-group"><label for="price">Harga</label><input id="price" type="number" name="price" value="<?=e($data['price'] ?? '')?>" required min="0" step="0.01"><?php if(isset($errors['price'])):?><p class="error-text"><?=e($errors['price'])?></p><?php endif?></div>
<div class="form-group"><label for="stock">Stok</label><input id="stock" type="number" name="stock" value="<?=e($data['stock'] ?? '')?>" required min="0" step="1"><?php if(isset($errors['stock'])):?><p class="error-text"><?=e($errors['stock'])?></p><?php endif?></div>
<div class="form-group"><label for="entry_date">Tanggal Masuk</label><input id="entry_date" type="date" name="entry_date" value="<?=e($data['entry_date'] ?? '')?>" required><?php if(isset($errors['entry_date'])):?><p class="error-text"><?=e($errors['entry_date'])?></p><?php endif?></div>
<div class="form-group"><label for="description">Deskripsi</label><textarea id="description" name="description" required><?=e($data['description'] ?? '')?></textarea><?php if(isset($errors['description'])):?><p class="error-text"><?=e($errors['description'])?></p><?php endif?></div></div><?php if($errors['form']??false):?><div class="alert alert-error"><?=e($errors['form'])?></div><?php endif?><div class="form-actions"><a href="index.php" class="btn btn-outline">Batal</a><button type="submit" class="btn btn-primary">Simpan Perubahan</button></div></form></section></main></div></body></html>